// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/random_number_generator.sol";

contract RandomNumberGeneratorTest is Test {
    RandomNumberGenerator rng;
    address player1 = makeAddr("player1");
    address player2 = makeAddr("player2");

    function setUp() public {
        rng = new RandomNumberGenerator();
        bytes32 saltSlot = bytes32(uint256(0)); // Assume salt is at slot 0
        vm.store(address(rng), saltSlot, bytes32(uint256(1))); // Set salt to 1
    }

    function test_RandomIsPredictableInSameBlock() public {
        uint256 bet = 1;
        vm.roll(1000); // Set fixed block number

        // Record and capture logs for first play
        vm.recordLogs();
        vm.prank(player1);
        rng.playGame(bet);
        Vm.Log[] memory logs1 = vm.getRecordedLogs();
        uint256 winningNumber1 = _parseWinningNumberLog(logs1);

        // Record and capture logs for second play
        vm.recordLogs();
        vm.prank(player2);
        rng.playGame(bet);
        Vm.Log[] memory logs2 = vm.getRecordedLogs();
        uint256 winningNumber2 = _parseWinningNumberLog(logs2);

        // Verify results are identical in same block
        assertEq(winningNumber1, winningNumber2, "Identical block should produce identical results");
    }

    function _parseWinningNumberLog(Vm.Log[] memory logs) internal pure returns (uint256) {
        // Match WinningNumberSet event signature
        bytes32 winningNumberEventSig = keccak256("WinningNumberSet(uint256)");

        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == winningNumberEventSig) {
                return abi.decode(logs[i].data, (uint256));
            }
        }
        revert("WinningNumberSet event not found");
    }
}
